import { useEffect, useState } from 'react';
import axios from '../../api/axiosInstance';

const Projects = () => {
    const [projects, setProjects] = useState([]);
    const [search, setSearch] = useState('');
    const [form, setForm] = useState({
        name: '', description: '', startDate: '', endDate: '',
        budget: '', progress: '', image: null
    });
    const [editId, setEditId] = useState(null);

    const fetchProjects = async () => {
        const res = await axios.get('/projects');
        setProjects(res.data);
    };

    useEffect(() => { fetchProjects(); }, []);

    const handleDelete = async (id) => {
        if (window.confirm('Bạn có chắc muốn xóa dự án này?')) {
            await axios.delete(`/projects/${id}`);
            fetchProjects();
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        const formData = new FormData();
        Object.keys(form).forEach(key => {
            if (form[key]) formData.append(key, form[key]);
        });

        if (editId) {
            await axios.put(`/projects/${editId}`, formData);
            alert('Đã cập nhật dự án!');
        } else {
            await axios.post('/projects', formData);
            alert('Đã thêm dự án!');
        }

        fetchProjects();
        setForm({ name: '', description: '', startDate: '', endDate: '', budget: '', progress: '', image: null });
        setEditId(null);
    };

    const handleEdit = (project) => {
        setForm({
            name: project.name,
            description: project.description,
            startDate: project.startDate?.slice(0, 10),
            endDate: project.endDate?.slice(0, 10),
            budget: project.budget,
            progress: project.progress,
            image: null
        });
        setEditId(project._id);
    };

    return (
        <div>
            <h2>📁 Danh sách Dự án</h2>

            <input
                type="text"
                placeholder="Tìm kiếm dự án..."
                onChange={(e) => setSearch(e.target.value)}
                style={{ marginBottom: '10px', padding: '8px', width: '300px' }}
            />

            <table border="1" cellPadding="10" width="100%">
                <thead>
                    <tr>
                        <th>Hình ảnh</th>
                        <th>Tên</th>
                        <th>Tiến độ (%)</th>
                        <th>Ngân sách</th>
                        <th>Bắt đầu</th>
                        <th>Kết thúc</th>
                        <th>Hành động</th>
                    </tr>
                </thead>
                <tbody>
                    {projects.filter(p => p.name.toLowerCase().includes(search.toLowerCase())).map(p => (
                        <tr key={p._id}>
                            <td><img src={p.image} alt="" width="60" /></td>
                            <td>{p.name}</td>
                            <td>{p.progress}%</td>
                            <td>{p.budget.toLocaleString()}đ</td>
                            <td>{p.startDate?.slice(0, 10)}</td>
                            <td>{p.endDate?.slice(0, 10)}</td>
                            <td>
                                <button onClick={() => handleEdit(p)} style={{ marginRight: 10 }}>✏️</button>
                                <button onClick={() => handleDelete(p._id)}>🗑️</button>
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>

            <hr style={{ margin: '40px 0' }} />
            <h3>{editId ? '🛠️ Chỉnh sửa Dự án' : '➕ Thêm Dự án mới'}</h3>

            <form onSubmit={handleSubmit} encType="multipart/form-data">
                <input type="text" placeholder="Tên dự án" required value={form.name}
                    onChange={e => setForm({ ...form, name: e.target.value })} /><br />

                <textarea placeholder="Mô tả" value={form.description}
                    onChange={e => setForm({ ...form, description: e.target.value })}></textarea><br />

                <input type="number" placeholder="Ngân sách" value={form.budget}
                    onChange={e => setForm({ ...form, budget: e.target.value })} /><br />

                <input type="number" placeholder="Tiến độ (%)" value={form.progress}
                    onChange={e => setForm({ ...form, progress: e.target.value })} /><br />

                <input type="date" value={form.startDate}
                    onChange={e => setForm({ ...form, startDate: e.target.value })} />
                <input type="date" value={form.endDate}
                    onChange={e => setForm({ ...form, endDate: e.target.value })} /><br />

                <input type="file" accept="image/*"
                    onChange={e => setForm({ ...form, image: e.target.files[0] })} /><br /><br />

                <button type="submit">{editId ? '💾 Lưu cập nhật' : '➕ Thêm mới'}</button>
            </form>
        </div>
    );
};

export default Projects;
